from .telegram_field import TelegramField


class DataInformationBlock(TelegramField):
    EXTENSION_BIT_MASK = 0x80  # 1000 0000
    FUNCTION_MASK = 0x30   # 0011 0000
    DATA_FIELD_MASK = 0x0F  # 0000 1111
    MORE_RECORDS_FOLLOW = 0x1F  # 0001 1111

    def __init__(self, parts=None):
        super(DataInformationBlock, self).__init__(parts)

    @property
    def has_extension_bit(self):
        """Check for extension bit on last byte"""
        try:
            return (self.parts[-1] & self.EXTENSION_BIT_MASK) > 0
        except IndexError:
            return False

    @property
    def has_lvar_bit(self):
        """returns true if first VIFE has LVAR active"""
        try:
            return (self.parts[0] & self.EXTENSION_BIT_MASK) > 0
        except IndexError:
            return False

    @property
    def is_eoud(self):
        """Check for end of user data bit VIF byte"""
        try:
            dif = self.parts[0]
            if dif in [0x0F, 0x1F]:
                return True
        except IndexError:
            pass

        return False

    @property
    def is_manufacturer_specific(self):
        """Check for manufacturer specific record"""
        try:
            dif = self.parts[0]
            if dif == 0x0F:
                return True
        except IndexError:
            pass

        return False

    @property
    def more_records_follow(self):
        try:
            dif = self.parts[0]
            return dif == self.MORE_RECORDS_FOLLOW
        except IndexError:
            pass

        return False

    @property
    def function_type(self):
        try:
            if self.is_eoud and self.more_records_follow:
                return FunctionType.MORE_RECORDS_FOLLOW

            if self.parts[0] == 0x0F:
                # Manufacturer Specific
                return FunctionType.SPECIAL_FUNCTION

            if self.parts[0] == 0x2F:
                return FunctionType.SPECIAL_FUNCTION_FILL_BYTE

            return FunctionType(
                (self.parts[0] & self.FUNCTION_MASK) >> 4)
        except IndexError:
            return None

    @property
    def is_variable_length(self):
        try:
            dif = self.parts[0]
            return (dif & self.DATA_FIELD_MASK) == 0x0D
        except IndexError:
            pass

        return False

    @property
    def length_encoding(self):
        try:
            len_enc = self.parts[0] & self.DATA_FIELD_MASK
        except IndexError:
            return (0, DataEncoding.ENCODING_NULL)

        # Fix length encoding values for cases where len_enc < 8,
        # to avoid negative lengths for BCD encodings:
        if len_enc in (9, 10, 11):
            # BCD length is len_enc - 8 > 0
            length = len_enc - 8
        elif len_enc == 12:
            length = len_enc - 7
        elif len_enc == 13:
            length = 6
        elif len_enc == 14:
            length = 6
        else:
            length = {
                0: 0,
                1: 1,
                2: 2,
                3: 3,
                4: 4,
                5: 4,
                6: 6,
                7: 8,
                8: 0,
                15: 0,
            }.get(len_enc, 0)

        encoding = {
            0: DataEncoding.ENCODING_NULL,
            1: DataEncoding.ENCODING_INTEGER,
            2: DataEncoding.ENCODING_INTEGER,
            3: DataEncoding.ENCODING_INTEGER,
            4: DataEncoding.ENCODING_INTEGER,
            5: DataEncoding.ENCODING_REAL,
            6: DataEncoding.ENCODING_INTEGER,
            7: DataEncoding.ENCODING_INTEGER,
            8: DataEncoding.ENCODING_NULL,
            9: DataEncoding.ENCODING_BCD,
            10: DataEncoding.ENCODING_BCD,
            11: DataEncoding.ENCODING_BCD,
            12: DataEncoding.ENCODING_BCD,
            13: DataEncoding.ENCODING_VARIABLE_LENGTH,
            14: DataEncoding.ENCODING_BCD,
            15: DataEncoding.ENCODING_NULL,
